  "„Anlage & Material“ ist im Verein nicht aktiviert.": "„Tesis ve malzeme“ kulüpte etkinleştirilmemiş.",
  "„Automatisch zugesagt“ ist empfohlen; bei aktiver Antwort gilt jede Person als offen, bis sie antwortet. Änderungen gelten für neue Termine.": "„Otomatik katıldı“ önerilir; etkin yanıtta herkes yanıt verene kadar açık sayılır. Değişiklikler yeni etkinlikler için geçerlidir.",
  "„Fällige Beiträge anlegen“ erzeugt für alle zugeordneten Mitglieder die Forderungen, die bis heute fällig sind – nie doppelt.": "„Vadesi gelen aidatları oluştur“ atanmış tüm üyeler için bugüne kadar vadesi gelen alacakları oluşturur – asla mükerrer değil.",
  "„Ich → Einstellungen → Einladen“ oder im Team „Person zur Mannschaft einladen“: persönlich per E-Mail oder als Mannschafts-Link bzw. QR-Code zum Selbstregistrieren. Bei Links gibst du neue Anfragen frei, bevor jemand die App nutzen kann.": "„Ben → Ayarlar → Davet et“ veya takımda „Kişiyi takıma davet et“: kişisel olarak e-postayla ya da kendi kaydını yapması için takım bağlantısı veya QR kodu olarak. Bağlantılarda, biri uygulamayı kullanmadan önce yeni istekleri sen onaylarsın.",
  "„Mannschaft bearbeiten → Spielplan importieren“: CSV-Datei aus dem DFBnet wählen, Vorschau prüfen (neu, geändert, unverändert, übersprungen) und übernehmen. Die Mannschaft bekommt eine Sammelmeldung. Ein erneuter Import aktualisiert Verlegungen, statt Spiele doppelt anzulegen. Innerhalb von 24 Stunden kannst du den Import rückgängig machen.": "„Takımı düzenle → Fikstürü içe aktar“: DFBnet'ten CSV dosyasını seç, önizlemeyi kontrol et (yeni, değişen, değişmeyen, atlanan) ve uygula. Takım toplu bir bildirim alır. Tekrar içe aktarma, maçları mükerrer oluşturmak yerine ertelemeleri günceller. İçe aktarmayı 24 saat içinde geri alabilirsin.",
  "„Team → Kader → Mannschaft bearbeiten“: Spieler aus der Vereinsliste hinzufügen oder aus dem Kader nehmen, Funktion (Spieler, Co-Trainer, Betreuer) und Rückennummer ändern, den Kassenwart bestimmen. Unten stellst du ein, wie viele Minuten vor Spielen und Trainings ihr euch trefft, den Standard-Treffpunkt und die Schreibweisen eurer Mannschaft im DFBnet. Co-Trainer haben dieselben Rechte wie der Trainer.": "„Takım → Kadro → Takımı düzenle“: Kulüp listesinden oyuncu ekle veya kadrodan çıkar, görevi (oyuncu, yardımcı antrenör, sorumlu) ve forma numarasını değiştir, veznedarı belirle. Aşağıda maçlardan ve antrenmanlardan kaç dakika önce buluşulacağını, standart buluşma yerini ve takımınızın DFBnet'teki yazımlarını ayarlarsın. Yardımcı antrenörler antrenörle aynı haklara sahiptir.",
  "„Team → Kasse → Kassenverwaltung“. Dort liegen als Kacheln: Einnahme/Ausgabe, Einzahlungen, Strafe vergeben, Getränke-Strichliste, Umlage, Beiträge, Buchungen & Storno, Kassenwart, Bezahlinfos und Kassenprüfung.": "„Takım → Kasa → Kasa yönetimi“. Orada kutucuklar halinde şunlar bulunur: gelir/gider, ödemeler, ceza ver, içecek çizelgesi, katkı payı, aidatlar, kayıtlar ve iptal, veznedar, ödeme bilgileri ve kasa denetimi.",
  "„Team → Termin anlegen“: Training, Spiel oder Mannschaftstermin. Spiele bekommen die Art Liga, Pokal oder Testspiel. Zum Wiederholen wählst du „Wöchentlich bis …“ und das Enddatum (bis zu etwa einem Jahr). Die Treffzeit berechnet die App aus den Regeln deiner Mannschaft; im einzelnen Termin kannst du sie überschreiben. Im Termin änderst du mit „Termin bearbeiten“ einzelne Termine oder „diesen und folgende“. Mit „Termin absagen“ wird die Mannschaft sofort benachrichtigt.": "„Takım → Etkinlik oluştur“: antrenman, maç veya takım etkinliği. Maçlar lig, kupa veya hazırlık maçı türünü alır. Tekrarlamak için „Haftalık, şu tarihe kadar …“ ve bitiş tarihini seç (yaklaşık bir yıla kadar). Buluşma saatini uygulama takımının kurallarından hesaplar; tek tek etkinlikte bunu değiştirebilirsin. Etkinlikte „Etkinliği düzenle“ ile tek tek etkinlikleri veya „bu ve sonraki“leri değiştirirsin. „Etkinliği iptal et“ ile takıma hemen bildirim gider.",
