  "auch mehrere auf einmal": "birden fazlası da aynı anda",
  "Auch Mitspieler sehen den Grund einer Absage oder Abwesenheit (z. B. verletzt, krank).": "Takım arkadaşları da ret veya yokluk nedenini görür (ör. sakat, hasta).",
  "Auch ohne Werbung bleibt der Sponsor in der Übersicht sichtbar.": "Reklam olmasa bile sponsor özette görünür kalır.",
  "Audit-Log einsehen": "Denetim kaydını gör",
  "Auf der letzten Seite findest du die passenden Schaltflächen.": "Uygun düğmeleri son sayfada bulursun.",
  "Auf der Startseite und unter „Verein → News“. Dringende Meldungen stehen oben und erreichen dich auch per Push. Mit „Gefällt mir“ und Kommentaren kannst du reagieren.": "Ana sayfada ve „Kulüp → Haberler“ altında. Acil bildirimler en üstte yer alır ve sana push ile de ulaşır. „Beğen“ ve yorumlarla tepki verebilirsin.",
  "Auf die Forderung wurde schon gezahlt. Storniere zuerst die Buchung im Kassenbuch.": "Bu alacak için zaten ödeme yapıldı. Önce kasa defterindeki kaydı iptal et.",
  "Auf jeder Unterseite siehst du oben deinen Weg, zum Beispiel „Team › Kasse › Strafenkatalog“. Tippe auf eine frühere Stufe, um dorthin zurückzugehen, oder auf den runden Pfeil für einen Schritt zurück. Bei langen Wegen steht „…“ für die ausgelassenen Stufen; ein Tipp zeigt sie als Liste. Die untere Leiste bleibt sichtbar, der aktuelle Bereich ist markiert.": "Her alt sayfanın üstünde yolunu görürsün, örneğin „Takım › Kasa › Ceza kataloğu“. Oraya dönmek için önceki bir basamağa, bir adım geri gitmek için yuvarlak oka dokun. Uzun yollarda „…“ atlanan basamakları gösterir; dokununca liste olarak görünür. Alt çubuk görünür kalır, mevcut alan işaretlidir.",
  "Auf Konto": "Hesaba",
  "auf später verschoben": "sonraya ertelendi",
  "Auf Start und unter Termine sagst du zu oder ab. Mit „Rückgängig“ nimmst du es gleich wieder zurück.": "Ana sayfada ve Etkinlikler altında katılırsın ya da reddedersin. „Geri al“ ile hemen geri alabilirsin.",
