  "Aus Datenschutzgründen siehst du nur Zahlen. Den Trainer der Mannschaft kannst du über „Ansprechpartner“ erreichen.": "Veri koruma nedeniyle yalnızca sayıları görürsün. Takımın antrenörüne „İletişim kişisi“ üzerinden ulaşabilirsin.",
