  "Aus diesen Regeln berechnet die App bei jedem neuen Spiel und Training die Treffzeit. Beim einzelnen Termin kannst du sie jederzeit überschreiben. Leer lassen = kein automatisches Treffen.": "Uygulama her yeni maç ve antrenman için buluşma saatini bu kurallardan hesaplar. Tek tek etkinlikte bunu istediğin zaman değiştirebilirsin. Boş bırakırsan otomatik buluşma olmaz.",
  "Aus einer Excel- oder CSV-Datei. Du siehst zuerst eine Vorschau – übernommen wird erst nach deiner Bestätigung.": "Bir Excel veya CSV dosyasından. Önce bir önizleme görürsün – onayından sonra uygulanır.",
