  "Beginnt am {0}. Kader planst du unter Verwaltung → Mitglieder: Mannschaften der neuen Saison sind dort mit „(Saison {1})“ gekennzeichnet.": "{0} tarihinde başlar. Kadroyu Yönetim → Üyeler altında planlarsın: yeni sezonun takımları orada „(Sezon {1})“ ile işaretlidir.",
  "Begründung": "Gerekçe",
  "Begründung (bei Ablehnung)": "Gerekçe (reddedilirse)",
  "Begründung für das Storno": "İptal gerekçesi",
  "Begünstigter Zweck": "Yararlanan amaç",
  "Bei „Nur der Kassenwart“ dürfen Trainer ohne Kassenwart-Aufgabe nichts mehr buchen und keine Strafen vergeben; sie sehen die Kasse weiterhin.": "„Yalnızca kasa sorumlusu“ seçilirse kasa sorumlusu görevi olmayan antrenörler artık kayıt yapamaz ve ceza veremez; kasayı görmeye devam ederler.",
  "Bei Auswärtsspielen und Turnieren gibt es im Termin den Bereich „Fahrgemeinschaften“. Tippe auf „Ich fahre“ und gib die freien Plätze an, oder wähle bei einem Auto „Mitfahren“. Wer keine Mitfahrt hat, tippt auf „Mitfahrt suchen“. Eltern buchen für ihre Kinder.": "Deplasman maçlarında ve turnuvalarda etkinlikte „Ortak yolculuklar“ bölümü bulunur. „Ben sürüyorum“a dokun ve boş yerleri belirt ya da bir arabada „Birlikte git“i seç. Yolculuğu olmayan „Yolculuk ara“ya dokunur. Ebeveynler çocukları için kayıt yapar.",
  "Bei der Anmeldung schicken wir dir einen 6-stelligen Code per E-Mail (10 Minuten gültig, nur einmal nutzbar). Sicherer ist eine Authenticator-App – der E-Mail-Code ist die einfachere Alternative.": "Girişte sana e-postayla 6 haneli bir kod göndeririz (10 dakika geçerli, yalnızca bir kez kullanılabilir). Kimlik doğrulama uygulaması daha güvenlidir – e-posta kodu daha basit bir alternatiftir.",
