  "Bei Terminen fehlt der Titel.": "Etkinliklerde başlık eksik.",
  "bei Terminen Pflicht, sonst automatisch": "etkinliklerde zorunlu, aksi halde otomatik",
  "Bei Terminen siehst du die Antwort für jede Person. Zu- und Absagen gelten je Kind.": "Etkinliklerde her kişinin yanıtını görürsün. Katılım ve retler çocuk başınadır.",
  "Bei Vereinsveranstaltungen (z. B. Jahreshauptversammlung, Turnier) kannst du Zusagen, Absagen oder „Unsicher“ wählen – ohne Begründung. Zusätzlich gibt es oft „Helfer gesucht“: Trage dich in eine Schicht ein.": "Kulüp etkinliklerinde (ör. genel kurul, turnuva) katılabilir, reddedebilir veya „Emin değilim“i seçebilirsin – gerekçe gerekmez. Ayrıca sık sık „Yardımcı aranıyor“ olur: bir vardiyaya yazıl.",
  "beidfüßig": "iki ayaklı",
  "Beidfüßig": "İki ayaklı",
  "Beim Austritt werden alle Mannschaftszuordnungen beendet, Rollen entzogen und der App-Zugang gesperrt. Die Daten bleiben für die Vereinsunterlagen erhalten.": "Ayrılışta tüm takım atamaları sona erer, roller alınır ve uygulama erişimi kapatılır. Veriler kulüp kayıtları için saklanır.",
  "Beim Buchen einer Einnahme wählst du den Sponsor aus (Verein → Sponsoren).": "Bir gelir kaydederken sponsoru seçersin (Kulüp → Sponsorlar).",
  "Beim Eigentor des Gegners gibt es keinen Torschützen.": "Rakibin kendi kalesine attığı golde golü atan oyuncu yoktur.",
  "Beim Kassenwart oder Trainerteam": "Veznedarda veya antrenör ekibinde",
  "Beim Löschen werden die automatischen Absagen zurückgenommen. Bei Mannschaften mit aktiver Zu-/Absage ist die Rückmeldung danach wieder offen.": "Silince otomatik retler geri alınır. Aktif katılım/ret kullanan takımlarda yanıt sonrasında yeniden açık olur.",
  "Beim Planen einer Veranstaltung wählst du oben die Gruppe („Ganzer Verein“, eine Abteilung …). Mit „Mannschaften oder Personen auswählen“ lädst du gezielt ein: Setze im Fenster Häkchen bei Mannschaften oder suche Personen. Die Auswahl erscheint als Chips; mit „×“ nimmst du jemanden wieder heraus. Nur die Eingeladenen werden benachrichtigt. Einzelne Personen darfst du nur mit dem Recht für die Mitgliederliste einladen.": "Bir etkinlik planlarken üstten grubu seçersin („Tüm kulüp“, bir bölüm …). „Takım veya kişi seç“ ile hedefli davet edersin: pencerede takımları işaretle veya kişileri ara. Seçim çipler olarak görünür; „×“ ile birini geri çıkarırsın. Yalnızca davet edilenlere bildirim gider. Tek tek kişileri yalnızca üye listesi yetkisiyle davet edebilirsin.",
  "Beim Start und nach einer Minute im Hintergrund fragt die App nach Face ID, Fingerabdruck oder dem Gerätecode. Die Einstellung gilt nur auf diesem Gerät.": "Açılışta ve arka planda bir dakika kaldıktan sonra uygulama Face ID, parmak izi veya cihaz kodunu ister. Bu ayar yalnızca bu cihazda geçerlidir.",
