  "Das Kürzel (2 bis 4 Zeichen, z. B. „SGW“) steht groß im Plakat der Startseite und ersetzt das Wappen, solange kein Logo hochgeladen ist. Die Vereinsadministration ändert es unter „Verwaltung → Verein & Design“, mit Vorschau. Die Vibration bei Auswahl und Bestätigung schaltest du auf dem Handy unter „Ich → Konto & Einstellungen → Vibration“ aus; bei eingestellter „Bewegung reduzieren“ des Geräts bleiben auch die Animationen aus.": "Kısaltma (2 ile 4 karakter, ör. „SGW“) ana sayfadaki afişte büyük görünür ve logo yüklenene kadar armanın yerini alır. Kulüp yönetimi bunu önizlemeyle „Yönetim → Kulüp ve tasarım“ altında değiştirir. Seçim ve onaydaki titreşimi telefonda „Ben → Hesap ve ayarlar → Titreşim“ altında kapatırsın; cihazda „Hareketi azalt“ ayarlıysa animasyonlar da kapalı kalır.",
  "Das Kürzel besteht aus 2 bis 4 Buchstaben oder Ziffern.": "Kısaltma 2 ile 4 harf veya rakamdan oluşur.",
  "Das Kürzel steht groß im Plakat auf der Startseite und ersetzt das Wappen, solange kein Logo hochgeladen ist.": "Kısaltma ana sayfadaki afişte büyük görünür ve logo yüklenene kadar armanın yerini alır.",
