  "Das Trainerteam sieht Grund und Freitext immer, Eltern die Gründe ihres Kindes. Ob auch die Mitspieler die Gründe sehen, stellt das Trainerteam in „Mannschaft bearbeiten“ ein („Abwesenheitsgründe für die Mannschaft sichtbar“, Standard aus).": "Antrenör ekibi neden ve serbest metni her zaman görür, ebeveynler çocuklarının nedenlerini görür. Takım arkadaşlarının da nedenleri görüp görmeyeceğini antrenör ekibi „Takımı düzenle“ altında ayarlar („Yokluk nedenleri takıma görünür“, varsayılan kapalı).",
