  "Deine Termine (und die deiner Kinder) sowie die Vereinstermine erscheinen automatisch in deinem Kalender – Änderungen und Absagen inklusive. Teilnehmerlisten werden nicht übertragen.": "Etkinliklerin (ve çocuklarının etkinlikleri) ile kulüp etkinlikleri takviminde otomatik görünür – değişiklikler ve iptaller dahil. Katılımcı listeleri aktarılmaz.",
