  "Der Kassenwart bucht Einnahmen, Ausgaben und Einzahlungen und pflegt den Strafenkatalog – gemeinsam mit dem Trainerteam. Infrage kommen Mitglieder mit eigenem Login und Eltern.": "Veznedar gelirleri, giderleri ve ödemeleri kaydeder ve ceza kataloğunu yönetir – antrenör ekibiyle birlikte. Kendi girişi olan üyeler ve ebeveynler olabilir.",
