  "Der Sponsor": "Sponsor",
  "Der Standard-Treffpunkt und die Minuten vor Beginn werden bei neuen Terminen vorbelegt.": "Standart buluşma yeri ve başlangıçtan önceki dakikalar yeni etkinliklerde otomatik doldurulur.",
