  "Der Termin": "Etkinlik",
  "Der Termin gehört nicht zu dieser Mannschaft.": "Etkinlik bu takıma ait değil.",
  "Der Termin gehört nicht zur Mannschaft.": "Etkinlik takıma ait değil.",
