  "Der Termin wurde abgesagt.": "Etkinlik iptal edildi.",
  "Der Untergrund je Platz hilft bei der Planung, z. B. wenn Rasenplätze gesperrt sind.": "Saha başına zemin türü planlamaya yardımcı olur, ör. çim sahalar kapalıyken.",
  "Der Verband setzt dich bei fremden Spielen ein. Trage den Einsatz hier ein, damit er in deinem Kalender steht und Überschneidungen mit deinen Terminen auffallen.": "Federasyon seni başka kulüplerin maçlarında görevlendirir. Görevi buraya gir; böylece takviminde yer alır ve etkinliklerinle çakışmalar fark edilir.",
  "Der Verein braucht mindestens einen Fulladmin.": "Kulübün en az bir tam yöneticisi olmalı.",
  "Der Verein ist bereits eingerichtet.": "Kulüp zaten kurulmuş.",
  "Der Verein kann mehrere Kassen führen, z. B. eine Jugendkasse. Unter „Admin-Verwaltung → Verein → Abteilungen“ legst du Abteilungen an (z. B. Senioren, Frauen, Jugend); danach fragt die App, ob die Abteilung eine eigene Kasse bekommen soll. Unter „Kassen“ legst du Kassen an, ordnest sie einer oder mehreren Abteilungen zu und bestimmst genau eine Hauptkasse. Ohne eigene Kasse laufen die Buchungen einer Abteilung über die Hauptkasse. Jede Kasse hat eigene Konten und Beiträge; in der Vereinskasse wechselst du oben zwischen „Alle“ und einer einzelnen Kasse. Kassen werden nie gelöscht, nur stillgelegt. Eine Umbuchung zwischen Konten verschiedener Kassen wird in beiden Kassen gebucht, ein Storno wirkt in beiden. Die Rolle Kassenwart (Verein) kann für den ganzen Verein oder nur für eine Abteilung vergeben werden und gilt dann nur für deren Kassen.": "Kulüp birden fazla kasa tutabilir, ör. bir gençlik kasası. „Yönetici paneli → Kulüp → Bölümler“ altında bölümler oluşturursun (ör. yetişkinler, kadınlar, gençlik); ardından uygulama bölümün kendi kasasının olup olmayacağını sorar. „Kasalar“ altında kasaları oluşturur, bir veya birden fazla bölüme atar ve tam olarak bir ana kasa belirlersin. Kendi kasası olmayan bir bölümün kayıtları ana kasa üzerinden yapılır. Her kasanın kendi hesapları ve aidatları vardır; kulüp kasasında üstte „Tümü“ ile tek bir kasa arasında geçiş yaparsın. Kasalar asla silinmez, yalnızca devre dışı bırakılır. Farklı kasaların hesapları arasındaki virman her iki kasaya da işlenir, iptal de her ikisinde geçerli olur. Veznedar (kulüp) rolü tüm kulüp için veya yalnızca bir bölüm için verilebilir ve o zaman yalnızca o bölümün kasaları için geçerlidir.",
  "Der Verein verlangt für deine Rolle die 2-Faktor-Anmeldung.": "Kulüp, rolün için iki faktörlü girişi zorunlu tutuyor.",
  "Der Verein verlangt für die Verwaltung die 2-Faktor-Anmeldung. Bitte unter „Konto & Sicherheit“ einrichten.": "Kulüp, yönetim için iki faktörlü girişi zorunlu tutuyor. Lütfen „Hesap ve güvenlik“ altında kur.",
  "Der Verein verlangt sie für deine Verwaltungsrechte. Bis dahin ist die Verwaltung gesperrt.": "Kulüp bunu yönetim yetkilerin için zorunlu tutuyor. O zamana kadar yönetim kilitli.",
  "Der Verein verlangt zu jeder Auslage einen Beleg. Bitte füge ein Foto oder eine Datei hinzu.": "Kulüp her masraf için fiş ister. Lütfen bir fotoğraf veya dosya ekle.",
  "Der Vermerk": "Not",
  "Der Vermerk wird entfernt.": "Not kaldırılacak.",
  "Der Verwendungszweck fehlt.": "Açıklama (ödeme amacı) eksik.",
  "Der volle Name steht auf Dokumenten, der Kurzname in der Kopfzeile und auf dem Wappen.": "Tam ad belgelerde, kısa ad başlıkta ve armada görünür.",
  "Der Vorstand sieht – wenn der Verein es in „Einsicht“ freigibt – unter „Verein → Vereinsleben → Kassenübersicht“ eine reine Anzeige: Kassenstand gesamt, Einnahmen und Ausgaben, die einzelnen Kassen und die Beitragsquote. Buchungen, Belege und Funktionen gibt es dort nicht; die Vereinskasse selbst führen Kassenwart und Kassenprüfer.": "Yönetim kurulu – kulüp „Görüntüleme“de izin verirse – „Kulüp → Kulüp hayatı → Kasa özeti“ altında salt görüntüleme görür: toplam kasa durumu, gelirler ve giderler, tek tek kasalar ve aidat tahsilat oranı. Orada kayıt, belge ve işlev yoktur; kulüp kasasını veznedar ve kasa denetçileri yönetir.",
  "Der Vorstand sieht auch Kassenbuch und Belege (ohne zu buchen)": "Yönetim kurulu kasa defterini ve belgeleri de görür (kayıt yapamaz)",
  "Der Vorstand sieht Kontostände und Summen, aber keine einzelnen Buchungen": "Yönetim kurulu hesap bakiyelerini ve toplamları görür, tek tek kayıtları görmez",
