  "Die Eingabe ist unvollständig oder ungültig.": "Giriş eksik veya geçersiz.",
  "Die Einrichtung hat nicht geklappt.": "Kurulum olmadı.",
  "Die Einstellung gilt für alle Mannschaften der Abteilung. Ist ein Modul hier aus, kann es keine Mannschaft darin einschalten. „Wie Verein“ übernimmt die Vereinseinstellung.": "Ayar bölümün tüm takımları için geçerlidir. Bir modül burada kapalıysa içindeki hiçbir takım onu açamaz. „Kulüp gibi“ kulüp ayarını devralır.",
  "Die Einstellung gilt nur auf diesem Gerät.": "Ayar yalnızca bu cihazda geçerlidir.",
  "Die Einstellung konnte nicht gespeichert werden.": "Ayar kaydedilemedi.",
  "Die Einstellung wurde nicht gespeichert.": "Ayar kaydedilmedi.",
  "Die Ergebnisse bleiben bis zum Ende der Frist verborgen.": "Sonuçlar sürenin sonuna kadar gizli kalır.",
  "Die Ergebnisse siehst du, sobald du abgestimmt hast.": "Sonuçları oy verir vermez görürsün.",
  "Die Ergebnisse sind für alle sichtbar.": "Sonuçlar herkese görünür.",
  "Die erste Zeile braucht mindestens die Spalten „Vorname“ und „Nachname“.": "İlk satırda en azından „Ad“ ve „Soyad“ sütunları olmalı.",
  "Die erste Zeile enthält die Spaltenüberschriften. Die Zuordnung zu den Feldern prüfst du im nächsten Schritt.": "İlk satır sütun başlıklarını içerir. Alanlarla eşleştirmeyi sonraki adımda kontrol edersin.",
