  "Die Frist für Korrekturen ist abgelaufen – nur der Admin kann die Anwesenheit noch ändern.": "Düzeltme süresi doldu – yoklamayı artık yalnızca yönetici değiştirebilir.",
  "Die Frist für Zu- und Absagen ist abgelaufen. Bitte wende dich an dein Trainerteam.": "Katılım ve ret süresi doldu. Lütfen antrenör ekibine başvur.",
  "Die Frist ist am {0}, {1} Uhr abgelaufen. Bei Änderungen wende dich an dein Trainerteam.": "Süre {0} tarihinde saat {1}'de doldu. Değişiklikler için antrenör ekibine başvur.",
  "Die Gastspielerbörse ist für den Verein nicht aktiviert.": "Konuk oyuncu borsası kulüpte etkinleştirilmemiş.",
  "Die Gastspielerbörse ist für Trainerteams und sportliche Leitung.": "Konuk oyuncu borsası antrenör ekipleri ve sportif yönetim içindir.",
  "Die gemeldete Zahlung über {0} ist noch nicht angekommen. Bitte wende dich an die Kasse.": "Bildirilen {0} tutarındaki ödeme henüz ulaşmadı. Lütfen kasaya başvur.",
  "Die gesetzliche Aufbewahrungsfrist läuft noch.": "Yasal saklama süresi hâlâ devam ediyor.",
  "Die Hauptkasse kann nicht stillgelegt werden. Lege zuerst eine andere Kasse als Hauptkasse fest.": "Ana kasa devre dışı bırakılamaz. Önce başka bir kasayı ana kasa olarak belirle.",
  "Die Hauptkasse nimmt Buchungen ohne Abteilungsbezug auf und kann nicht stillgelegt werden. Lege eine andere Kasse als Hauptkasse fest, um zu wechseln.": "Ana kasa bölümle ilişkisi olmayan kayıtları alır ve devre dışı bırakılamaz. Değiştirmek için başka bir kasayı ana kasa olarak belirle.",
  "Die importierten Einträge wurden wieder entfernt, aktualisierte Werte zurückgesetzt.": "İçe aktarılan kayıtlar kaldırıldı, güncellenen değerler geri alındı.",
  "Die Kaderliste ist für dich nicht freigegeben.": "Kadro listesi senin için açık değil.",
  "Die Kasse": "Kasa",
  "Die Kasse bestätigt den Eingang – erst dann ist dein Konto ausgeglichen.": "Kasa ödemenin ulaştığını onaylar – ancak o zaman hesabın dengelenir.",
  "Die Kasse ist stillgelegt.": "Kasa devre dışı.",
  "Die Kasse konnte nicht vollständig eingerichtet werden.": "Kasa tam olarak kurulamadı.",
  "Die Kasse wird bei der Kassenprüfung des Vereins berücksichtigt": "Kasa, kulübün kasa denetiminde dikkate alınır",
  "Die Kassenprüfung machen Kassenprüfer.": "Kasa denetimini kasa denetçileri yapar.",
  "Die Kassenprüfung machen Kassenprüfer. Hier siehst du die abgegebenen Prüfberichte.": "Kasa denetimini kasa denetçileri yapar. Burada teslim edilen denetim raporlarını görürsün.",
  "Die Kassenstatistik sieht die Mannschaft.": "Kasa istatistiğini takım görür.",
  "Die Kassenverwaltung ist für Kassenwart und Trainerteam.": "Kasa yönetimi veznedar ve antrenör ekibi içindir.",
  "Die Kategorie": "Kategori",
  "Die Kategorie „{0}“ gilt für Ausgaben.": "„{0}“ kategorisi giderler için geçerlidir.",
  "Die Kategorie „{0}“ gilt für Einnahmen.": "„{0}“ kategorisi gelirler için geçerlidir.",
  "Die Kategorie ist archiviert.": "Kategori arşivlenmiş.",
  "Die Kennzahl zeigt auf einen Blick, was dort los ist: bei Terminen und Veranstaltungen das Datum des nächsten (TT.MM.), beim Kader die Zahl der Spieler, bei der Statistik die Bilanz (Siege-Remis-Niederlagen), bei der Kasse den Kassenstand, bei Aufgaben und Umfragen die offenen, bei News, Dokumenten und Wissen die neuen, beim Spielplan die Spiele der Woche, bei Helfern die freien Plätze. Orange heißt: Hier wartet etwas auf dich. Kacheln ohne sinnvolle Zahl haben keine Kennzahl.": "Gösterge, orada neler olduğunu tek bakışta gösterir: etkinliklerde ve organizasyonlarda bir sonrakinin tarihi (GG.AA.), kadroda oyuncu sayısı, istatistikte bilanço (galibiyet-beraberlik-mağlubiyet), kasada kasa durumu, görevlerde ve anketlerde açık olanlar, haberlerde, belgelerde ve bilgide yeniler, fikstürde haftanın maçları, yardımcılarda boş yerler. Turuncu: Seni bekleyen bir şey var. Anlamlı bir sayısı olmayan kutucukların göstergesi yoktur.",
  "Die kleine Zeile unter dem Namen einer Kachel zeigt, was für dich gerade wichtig ist, z. B. „Du hast 12,50 € offen“, „Antwort fehlt“ oder „2 zur Freigabe“. Die Farbe verstärkt den Text: Orange heißt, es gibt etwas zu tun. Was du nicht sehen darfst, wird nicht angezeigt.": "Bir kutucuğun adının altındaki küçük satır, şu an senin için neyin önemli olduğunu gösterir, ör. „12,50 € açığın var“, „Yanıt eksik“ veya „2 onaya“. Renk metni güçlendirir: Turuncu, yapılacak bir şey var demektir. Görmeye yetkin olmayan şeyler gösterilmez.",
