  "Die Spende wird als Einnahme im Kassenbuch gebucht. Mit ausgestellter Bestätigung kann die Buchung nicht mehr storniert werden.": "Bağış kasa defterine gelir olarak kaydedilir. Onay belgesi düzenlendikten sonra kayıt iptal edilemez.",
