  "Die Steuerdaten des Vereins sind noch nicht vollständig. Die Administration trägt sie ein und gibt die Vorlage nach rechtlicher Prüfung frei.": "Kulübün vergi bilgileri henüz tam değil. Yönetici bunları girer ve şablonu hukuki kontrolden sonra onaylar.",
  "Die Steuerdaten pflegt die Vereinsadministration (Vereinskasse › Steuerdaten).": "Vergi bilgilerini kulüp yönetimi girer (Kulüp kasası › Vergi bilgileri).",
