  "Die Veranstaltung wurde nicht gefunden.": "Organizasyon bulunamadı.",
  "Die Vereinseinstellungen ändert die Vereinsadministration.": "Kulüp ayarlarını kulüp yönetimi değiştirir.",
  "Die Vereinskasse einrichten": "Kulüp kasasını kur",
  "Die Vereinskasse führt der Kassenwart (Verein).": "Kulüp kasasını veznedar (kulüp) yönetir.",
  "Die Vereinskasse führt nur die Kassenführung.": "Kulüp kasasını yalnızca kasa yönetimi yönetir.",
  "Die Vereinskasse ist nicht aktiviert.": "Kulüp kasası etkinleştirilmemiş.",
  "Die Vereinskasse ist von den Mannschaftskassen getrennt und liegt unter „Verein → Vereinskasse“ (wenn das Modul aktiv ist). Der Kassenwart (Verein) legt Konten mit Anfangsbestand an, bucht Einnahmen und Ausgaben mit Kategorie, optionaler Kostenstelle, Belegnummer und Belegfoto und bucht um zwischen Konten. Buchungen werden nie gelöscht, sondern mit Begründung storniert. Die Kategorien gehören zu den vier steuerlichen Bereichen (ideell, Vermögensverwaltung, Zweckbetrieb, wirtschaftlicher Geschäftsbetrieb). Kassenprüfer lesen alles, buchen aber nicht. Wer außerdem einsehen darf (z. B. der Vorstand), stellt die Vereinsadministration unter „Einrichtung“ ein.": "Kulüp kasası takım kasalarından ayrıdır ve „Kulüp → Kulüp kasası“ altındadır (modül aktifse). Veznedar (kulüp) başlangıç bakiyeli hesaplar oluşturur, gelirleri ve giderleri kategori, isteğe bağlı masraf merkezi, belge numarası ve belge fotoğrafıyla kaydeder ve hesaplar arasında virman yapar. Kayıtlar asla silinmez, gerekçeyle iptal edilir. Kategoriler dört vergi alanına aittir (ideal, varlık yönetimi, amaç işletmesi, ticari işletme). Kasa denetçileri her şeyi okur ama kayıt yapmaz. Başka kimlerin görüntüleyebileceğini (ör. yönetim kurulu) kulüp yönetimi „Kurulum“ altında ayarlar.",
  "Die Vereinskasse sehen nur Kassenführung und Prüfer.": "Kulüp kasasını yalnızca kasa yönetimi ve denetçiler görür.",
  "Die Verwaltung ist für Vorstand, Leitung und Administration.": "Yönetim, yönetim kurulu, bölüm yönetimi ve yöneticiler içindir.",
  "Die Vorlage ist noch nicht freigegeben. Sie muss zuerst rechtlich bzw. steuerlich geprüft werden.": "Şablon henüz onaylanmadı. Önce hukuki veya vergi açısından kontrol edilmeli.",
  "Die Vorlage mit Beispielzeile und Spaltenerklärung lädst du in der Web-Verwaltung herunter.": "Örnek satırlı ve sütun açıklamalı şablonu web yönetiminden indirirsin.",
  "Die Vorlage muss zuerst rechtlich bzw. steuerlich geprüft und von der Administration freigegeben werden.": "Şablon önce hukuki veya vergi açısından kontrol edilmeli ve yönetici tarafından onaylanmalı.",
  "Die Vorlage schaltet passende Funktionen für die Mannschaft ein.": "Şablon takım için uygun işlevleri açar.",
  "Die Werte anderer Spieler sieht nur die Mannschaft.": "Diğer oyuncuların değerlerini yalnızca takım görür.",
