  "Diese Bedingungen gelten für die Nutzung der App und der Web-Verwaltung von Clubroof durch Vereine und ihre Mitglieder.": "Bu koşullar, Clubroof uygulamasının ve web yönetiminin kulüpler ve üyeleri tarafından kullanımı için geçerlidir.",
