  "Diese Rechte gelten zusätzlich zu den Rollen und immer für den ganzen Verein. Für ein Recht nur in einer Mannschaft oder einer Abteilung lieber eine Rolle mit Geltungsbereich vergeben.": "Bu yetkiler rollere ek olarak geçerlidir ve her zaman tüm kulüp içindir. Yalnızca bir takımda veya bölümde geçerli bir yetki için kapsamlı bir rol vermek daha iyidir.",
  "Diese Rolle enthält vereinsweite Rechte und gilt nur für den ganzen Verein.": "Bu rol kulüp genelinde yetkiler içerir ve yalnızca tüm kulüp için geçerlidir.",
