  "du hast angefordert, dein Passwort für die Vereins-App zurückzusetzen. Öffne diesen Link": "kulüp uygulaması için şifreni sıfırlamak istedin. Şu bağlantıyı aç",
  "Du hast das Recht auf Auskunft, Berichtigung, Löschung, Einschränkung und Datenübertragbarkeit. Wende dich dazu an deinen Verein oder an den Support.": "Bilgi alma, düzeltme, silme, kısıtlama ve veri taşınabilirliği hakkın var. Bunun için kulübüne veya desteğe başvur.",
