  "Du kannst weitere Anlagen ergänzen und alles später in der Verwaltung ändern.": "Başka tesisler ekleyebilir ve her şeyi daha sonra yönetimden değiştirebilirsin.",
  "Du siehst den Vereinsüberblick, alle Vereinstermine und News, kannst bei Veranstaltungen zu- oder absagen und dich als Helfer eintragen. Eigene News kannst du schreiben; sie werden nach Freigabe durch den Vorstand veröffentlicht.": "Kulüp özetini, tüm kulüp etkinliklerini ve haberleri görürsün, organizasyonlara katılabilir veya reddedebilir ve kendini yardımcı olarak kaydedebilirsin. Kendi haberlerini yazabilirsin; yönetim kurulu onayından sonra yayınlanır.",
