  "Ein Beleg schützt bei der Kassenprüfung. Die zweite Freigabe verhindert, dass eine Person allein größere Beträge anweist.": "Fiş, kasa denetiminde korur. İkinci onay, tek bir kişinin büyük tutarları tek başına talimatlandırmasını önler.",
