  "Ein kurzer Willkommenstext erscheint im Team-Tab – zum Beispiel zu Kleidung, Treffpunkten und Regeln.": "Takım sekmesinde kısa bir karşılama metni görünür – örneğin kıyafet, buluşma yerleri ve kurallar hakkında.",
  "Ein Mannschafts-Link (oder QR-Code als Aushang) lässt neue Spieler und Eltern eine Beitrittsanfrage stellen. Du gibst jede Anfrage frei. Ein neuer Link macht den alten ungültig.": "Bir takım bağlantısı (veya ilan olarak QR kodu) yeni oyuncuların ve ebeveynlerin katılım isteği göndermesini sağlar. Her isteği sen onaylarsın. Yeni bir bağlantı eskisini geçersiz kılar.",
