  "Ein Team": "Bir takım",
  "Ein Verein mit nur einer Administration ist ein Risiko: Fällt die Person aus, kommt niemand mehr an die Einstellungen. Bestimme eine zweite Person mit denselben Rechten.": "Tek yöneticisi olan bir kulüp risktir: o kişi yoksa kimse ayarlara ulaşamaz. Aynı haklara sahip ikinci bir kişi belirle.",
  "Ein zusätzlicher Schutz: Nach dem Passwort fragt die App einen Code ab – aus einer Authenticator-App oder per E-Mail (6 Stellen, 10 Minuten gültig, nur einmal nutzbar). Du richtest ihn unter „Ich → Konto & Einstellungen“ ein. Pflicht ist er nur für das Administrationskonto, wenn der Verein es verlangt.": "Ek bir koruma: Şifreden sonra uygulama bir kod ister – kimlik doğrulama uygulamasından veya e-postayla (6 hane, 10 dakika geçerli, yalnızca bir kez kullanılabilir). Bunu „Ben → Hesap ve ayarlar“ altında kurarsın. Yalnızca kulüp isterse yönetici hesabı için zorunludur.",
