  "Einzeln unter „Mitglieder → Mitglied anlegen“ oder per Import aus Excel oder CSV („Importieren“): Bereich wählen, Vorlage laden, Datei hochladen, Spalten zuordnen, Vorschau prüfen (neu, aktualisiert, Dublette, Fehler), bei Dubletten überspringen, aktualisieren oder neu anlegen. Der Import wird ganz oder gar nicht übernommen und lässt sich 24 Stunden lang rückgängig machen. Austritte beenden Mannschaftszugehörigkeiten und sperren den App-Zugang. In der Mitgliederliste filterst du nach Rolle, Trainerteam, individuellen Rechten oder fehlendem App-Zugang.": "Tek tek „Üyeler → Üye oluştur“ altında veya Excel ya da CSV'den içe aktarma ile („İçe aktar“): alanı seç, şablonu yükle, dosyayı yükle, sütunları eşleştir, önizlemeyi kontrol et (yeni, güncellenen, mükerrer, hata), mükerrerlerde atla, güncelle veya yeni oluştur. İçe aktarma ya tamamen ya hiç uygulanmaz ve 24 saat boyunca geri alınabilir. Ayrılışlar takım üyeliklerini sonlandırır ve uygulama erişimini kapatır. Üye listesinde role, antrenör ekibine, bireysel yetkilere veya eksik uygulama erişimine göre filtrelersin.",
