  "Erinnerung, Bezahlinfos und Kassenprüfung?": "Hatırlatma, ödeme bilgileri ve kasa denetimi?",
  "Erinnerungen": "Hatırlatmalar",
  "Erinnerungen an offene Beträge verschickst du per Knopf oder lässt sie monatlich automatisch laufen (Einstellungen). Unter „Bezahlinfos & Einstellungen“ hinterlegst du IBAN und PayPal und bestimmst, ob alle die Beträge aller Beteiligten sehen (Standard: jeder nur die eigenen; Kassenstand, Einnahmen und Ausgaben sieht immer die ganze Mannschaft). „Kassenprüfung“ hält den Stand mit Prüfer fest. Berichte gibt es als Excel und PDF.": "Açık tutarlar için hatırlatmaları düğmeyle gönderir veya aylık otomatik çalışmasını sağlarsın (Ayarlar). „Ödeme bilgileri ve ayarlar“ altında IBAN ve PayPal bilgilerini girer, herkesin tüm katılımcıların tutarlarını görüp görmeyeceğini belirlersin (varsayılan: herkes yalnızca kendi tutarını görür; kasa durumunu, gelirleri ve giderleri her zaman tüm takım görür). „Kasa denetimi“ durumu denetçiyle birlikte kaydeder. Raporlar Excel ve PDF olarak mevcuttur.",
