  "Es erscheint oben in der App bei allen Mitgliedern. Ohne Logo zeigt die App ein Wappen mit dem Kürzel.": "Uygulamanın üstünde tüm üyelerde görünür. Logo yoksa uygulama kısaltmalı bir arma gösterir.",
  "Es fehlen {0} aktive Schiedsrichter": "{0} aktif hakem eksik",
  "Es fehlen zugeordnete Pflichtfelder.": "Eşleştirilmiş zorunlu alanlar eksik.",
