  "Es gibt bereits Kategorien.": "Zaten kategoriler var.",
  "Es gibt keine Einnahmekategorie für Beiträge. Lege sie in der Vereinskasse an.": "Aidatlar için gelir kategorisi yok. Kulüp kasasında oluştur.",
  "Es gibt keine neuen Mitglieder zu übernehmen.": "Uygulanacak yeni üye yok.",
  "Es gibt nichts zu übernehmen.": "Uygulanacak bir şey yok.",
  "Es gibt noch fehlerhafte Zeilen. Bitte korrigieren oder abwählen.": "Hâlâ hatalı satırlar var. Lütfen düzelt veya seçimi kaldır.",
  "Es gibt noch keine Erwachsenen mit Login in der Mannschaft.": "Takımda henüz girişi olan yetişkin yok.",
  "Es gibt noch keine Kategorien für diese Art. Lege sie unter „Einrichtung“ an.": "Bu tür için henüz kategori yok. „Kurulum“ altında oluştur.",
  "Es gibt nur einen Fulladmin – lege einen zweiten an.": "Yalnızca bir tam yönetici var – ikincisini oluştur.",
  "Es gibt zwei Wege: Unter „Ich“ stehen direkt unter deinem Profil die zwei farbigen Knöpfe „Admin-Verwaltung“ (violett) und „Vereinskasse“ (blau) – nur die, für die du Rechte hast. Außerdem steht unter „Verein“ in der Gruppe „Meine Vereinsaufgaben“ der Zugang zur „Verwaltung“ (für alle mit Verwaltungsrechten) und zur „Vereinskasse“ (für alle mit Kassenzugriff); am Desktop stehen beide dauerhaft in der Seitenleiste. Beide öffnen einen eigenen Bereich mit farbigem Kopfband und „Zur App“ oben sowie einer Leiste mit Reitern unten. Die Verwaltung hat die Reiter Übersicht, Mitglieder, Sport, Inhalte und Verein – du siehst nur, wofür du Rechte hast. In der Vereinskasse gibt es Übersicht, Buchung, Beiträge, Planung und Auswertung. Funktionen mit „Bald verfügbar“ folgen in einem späteren Update.": "İki yol var: „Ben“ altında profilinin hemen altında „Yönetici paneli“ (mor) ve „Kulüp kasası“ (mavi) renkli düğmeleri bulunur – yalnızca yetkin olanlar. Ayrıca „Kulüp“ altında „Kulüp görevlerim“ grubunda „Yönetim“ (yönetim yetkisi olan herkes için) ve „Kulüp kasası“ (kasa erişimi olan herkes için) erişimi yer alır; masaüstünde ikisi de kalıcı olarak kenar çubuğundadır. İkisi de renkli başlık bandı ve üstte „Uygulamaya“ ile altta sekmeli bir çubuk içeren ayrı bir alan açar. Yönetimin sekmeleri Özet, Üyeler, Spor, İçerikler ve Kulüp'tür – yalnızca yetkin olanları görürsün. Kulüp kasasında Özet, Kayıt, Aidatlar, Planlama ve Rapor vardır. „Yakında müsait“ yazan işlevler sonraki bir güncellemede gelecek.",
  "Es ist ein unerwarteter Fehler aufgetreten.": "Beklenmeyen bir hata oluştu.",
