  "Feste Gruppen müssen nicht ständig antworten – „Automatisch zugesagt“ spart Nachfragen und zeigt trotzdem, wer fehlt. Bei Spielen ist die aktive Antwort oft sinnvoller, weil der Kader begrenzt ist.": "Sabit gruplar sürekli yanıt vermek zorunda değil – „Otomatik katıldı“ gereksiz soruları önler ve yine de kimin eksik olduğunu gösterir. Maçlarda kadro sınırlı olduğu için etkin yanıt çoğu zaman daha mantıklıdır.",
