  "Für Zuwendungsbestätigungen braucht der Verein Angaben aus dem Freistellungsbescheid. Das trägt die Vereinsadministration ein; die Vorlage wird erst nach rechtlicher Prüfung freigegeben.": "Bağış belgeleri için kulübün muafiyet belgesindeki bilgilere ihtiyacı vardır. Bunları kulüp yönetimi girer; şablon yalnızca hukuki incelemeden sonra onaylanır.",
  "Fuß: {0}": "Ayak: {0}",
  "Ganz unten auf Start findest du den Schnellzugriff – Abkürzungen zu Seiten, die du oft brauchst. Tippe auf „Hinzufügen“, wähle die Einträge aus und speichere. „Zurücksetzen“ stellt die Voreinstellung für deine Rolle wieder her. Die Auswahl gilt auf allen deinen Geräten.": "Ana sayfanın en altında hızlı erişimi bulursun – sık kullandığın sayfalara kısayollar. „Ekle“ye dokun, kayıtları seç ve kaydet. „Sıfırla“ rolün için varsayılan ayarı geri yükler. Seçim tüm cihazlarında geçerlidir.",
