  "Gehört das Geld dem Verein, muss es in dessen Büchern auftauchen. Klärt das bitte mit dem Kassenwart des Vereins.": "Para kulübe aitse, kulübün defterlerinde görünmelidir. Lütfen bunu kulübün kasa sorumlusuyla netleştirin.",
