  "Gelöscht – lässt sich wiederherstellen": "Silindi – geri yüklenebilir",
  "Gelöschte Einträge liegen hier und lassen sich wiederherstellen. Endgültig gelöscht wird nie automatisch, sondern nur auf deinen Anstoß.": "Silinen kayıtlar burada durur ve geri yüklenebilir. Kalıcı silme asla otomatik olmaz, yalnızca senin isteğinle olur.",
  "Gelöschte Rollen": "Silinen roller",
  "Gelöschte Rollen lassen sich wiederherstellen.": "Silinen roller geri yüklenebilir.",
  "Gelöschte Wissensartikel, Übungen, Aufgaben, Sponsoren, Dokumente und ausgemustertes Material landen im Archiv; bei Dokumenten bleibt die Datei erhalten, bis das Archiv bereinigt wird. Das Trainerteam öffnet das Archiv seiner Mannschaft unter „Team → Archiv“ (gelöschte Aufgaben und Dokumente, wiederherstellen). Die Administration öffnet das ganze Archiv unter „Verwaltung → Abo & Kontrolle → Archiv“: Dort stellst du einen Eintrag mit „Wiederherstellen“ wieder her. Ist sein Name inzwischen vergeben, fragt dich die App nach einem neuen Namen. Endgültig gelöscht wird nie automatisch: „Bereinigen“ entfernt, was älter als die Standardfrist ist (derzeit 2 Jahre), „Archiv leeren“ löscht alles; beides nur auf deinen Anstoß und mit Bestätigung. „Archiv exportieren“ speichert alle archivierten Einträge als Datei.": "Silinen bilgi makaleleri, alıştırmalar, görevler, sponsorlar, belgeler ve kullanımdan çıkarılan malzemeler arşive düşer; belgelerde dosya, arşiv temizlenene kadar saklanır. Antrenör ekibi takımının arşivini „Takım → Arşiv“ altında açar (silinen görevler ve belgeler, geri yükleme). Yönetici tüm arşivi „Yönetim → Abonelik ve kontrol → Arşiv“ altında açar: orada bir kaydı „Geri yükle“ ile geri yüklersin. Adı bu arada başkasına verilmişse uygulama sana yeni bir ad sorar. Kalıcı silme asla otomatik olmaz: „Temizle“ standart süreden eski olanları kaldırır (şu an 2 yıl), „Arşivi boşalt“ her şeyi siler; ikisi de yalnızca senin isteğinle ve onayla. „Arşivi dışa aktar“ arşivlenmiş tüm kayıtları dosya olarak kaydeder.",
  "Gemeinnützig": "Kamu yararına",
  "Gemeinnützige Vereine müssen Einnahmen und Ausgaben steuerlich trennen. Ist der Verein nicht gemeinnützig, reicht eine einfachere Kategorieliste.": "Kamu yararına dernekler gelir ve giderleri vergi açısından ayırmak zorundadır. Kulüp kamu yararına değilse daha basit bir kategori listesi yeterlidir.",
