  "Hallo {0},": "Merhaba {0},",
  "Hallo {0},\n\ndeine Anfrage für {1} wurde freigegeben. Du kannst dich jetzt in der App anmelden:\n\n{2}": "Merhaba {0},\n\n{1} için isteğin onaylandı. Artık uygulamaya giriş yapabilirsin:\n\n{2}",
  "Hallo {0},\n\ndeine Anfrage für {1} wurde leider nicht freigegeben.{2}": "Merhaba {0},\n\n{1} için isteğin maalesef onaylanmadı.{2}",
  "Hallo, {0}": "Merhaba, {0}",
  "Hallo, Maximilian-Alexander von Hohenzollern-Sigmaringen": "Merhaba, Maximilian-Alexander von Hohenzollern-Sigmaringen",
  "Hallo! Wir nutzen Clubroof für {0}: Termine, Zu- und Absagen und alle Infos an einem Ort. Hier kommst du in die Mannschaft: {1}": "Merhaba! {0} için Clubroof kullanıyoruz: etkinlikler, katılım ve retler ve tüm bilgiler tek yerde. Takıma buradan katılabilirsin: {1}",
  "Hält den Kassenstand von heute fest – z. B. nach der Kassenprüfung oder zum Saisonende. Der Abschluss erscheint auch im Kassenbericht. Beim Saisonwechsel geht die Kasse automatisch auf die neue Mannschaft über.": "Bugünkü kasa durumunu kaydeder – ör. kasa denetiminden sonra veya sezon sonunda. Kapanış kasa raporunda da görünür. Sezon geçişinde kasa otomatik olarak yeni takıma geçer.",
  "Halte die Kamera auf den QR-Code deiner Einladung.": "Kamerayı davetindeki QR koduna tut.",
  "Hartplatz": "Sert zemin",
  "Hat eine Abteilung eigenes Geld (z. B. die Jugend), bekommt sie eine eigene Kasse. Wer die Abteilung leitet, sieht dann nur diese Kasse. Optional.": "Bir bölümün kendi parası varsa (örn. gençlik), kendi kasasını alır. Bölümü yöneten kişi o zaman yalnızca bu kasayı görür. İsteğe bağlı.",
