  "Importiere zuerst die Mitgliederliste mit Geburtsdaten. Danach kannst du die Zuordnung unter Vereinskasse › Beiträge nachholen.": "Önce doğum tarihli üye listesini içe aktar. Ardından atamayı Kulüp kasası › Aidatlar altında yapabilirsin.",
  "Importieren": "İçe aktar",
  "Importierte Einträge werden schon verwendet. Der Import lässt sich nicht mehr rückgängig machen.": "İçe aktarılan kayıtlar zaten kullanılıyor. İçe aktarma artık geri alınamaz.",
