  "Je Spiel in der Aufstellung": "Dizilişte maç başına",
  "Je Spiel: die Nummer wird bei jeder Aufstellung neu vergeben. Fest: eine Nummer pro Spieler für die ganze Saison.": "Maç başına: numara her kadroda yeniden verilir. Sabit: tüm sezon için oyuncu başına bir numara.",
  "Je Sponsor": "Sponsor başına",
  "Jede Änderung setzt die Freigabe der Vorlage zurück.": "Her değişiklik şablonun onayını sıfırlar.",
  "Jede Kasse hat eigene Konten, Beiträge und Auswertung. Ohne Zuordnung läuft eine Abteilung über die Hauptkasse. Der Jahresabschluss gilt immer für den ganzen Verein.": "Her kasanın kendi hesapları, aidatları ve raporu vardır. Atama yoksa bir bölüm ana kasa üzerinden işler. Yıl kapanışı her zaman tüm kulüp için geçerlidir.",
  "Jede Leitung sieht nur Daten ihrer Abteilung": "Her yönetici yalnızca kendi bölümünün verilerini görür",
  "Jede Mannschaft legt fest, bis wann Zu- und Absagen möglich sind. Der Countdown steht am Termin („Frist: Noch 2 Tage“). Danach bleibt deine Antwort sichtbar (Schloss „Frist abgelaufen“), ändern kann sie nur dein Trainerteam.": "Her takım, katılım ve retlerin ne zamana kadar mümkün olduğunu belirler. Geri sayım etkinlikte yer alır („Süre: 2 gün kaldı“). Sonrasında yanıtın görünür kalır (kilit „Süre doldu“), yalnızca antrenör ekibin değiştirebilir.",
  "Jede Person sagt zu oder ab – der Trainer sieht, wer noch fehlt": "Herkes katılır veya reddeder – antrenör kimin eksik olduğunu görür",
  "Jede Zeile ist grün (neu), blau (aktualisiert), gelb (Dublette) oder rot (Fehler). Abgewählte Zeilen werden nicht übernommen.": "Her satır yeşil (yeni), mavi (güncellenen), sarı (mükerrer) veya kırmızıdır (hata). Seçimi kaldırılan satırlar uygulanmaz.",
  "Jeder Spieler behält seine Nummer; sie erscheint im Kader und in der Aufstellung.": "Her oyuncu numarasını korur; kadroda ve dizilişte görünür.",
  "Jeder Spieler der Startelf braucht einen Platz der Formation.": "İlk 11'deki her oyuncunun dizilişte bir yeri olmalı.",
  "Jedes Feld kann nur einer Spalte zugeordnet werden.": "Her alan yalnızca bir sütunla eşleştirilebilir.",
  "Jedes Mitglied reicht unter „Verein → Auslage einreichen“ Kosten mit Beleg (Foto) oder Fahrtkosten ein – bei Fahrtkosten rechnet die App aus den Kilometern (30 Cent je km). Der Kassenwart sieht die Auslagen unter „Vereinskasse → Buchung → Auslagen“, genehmigt oder lehnt mit Begründung ab und erstattet: Dabei entsteht eine Ausgabe im Kassenbuch. Du bekommst zu jedem Schritt eine Benachrichtigung. Eine erstattete Auslage kann nicht storniert werden.": "Her üye „Kulüp → Harcama gönder“ altında belgeli (fotoğraf) masrafları veya yol masraflarını gönderir – yol masraflarında uygulama kilometreden hesaplar (km başına 30 sent). Veznedar harcamaları „Kulüp kasası → Kayıt → Harcamalar“ altında görür, onaylar veya gerekçeyle reddeder ve iade eder: bu sırada kasa defterinde bir gider oluşur. Her adım için bildirim alırsın. İade edilmiş bir harcama iptal edilemez.",
