  "Kassenprüfer": "Kasa denetçisi",
  "Kassenprüfer beginnen unter „Vereinskasse → Auswertung → Kassenprüfung“ eine Prüfung für ein Jahr – für den ganzen Verein oder nur für ihre Kasse. Die App zieht auf Wunsch zufällige Stichproben; jede Buchung wird abgehakt oder mit Begründung beanstandet, den Beleg siehst du direkt. Dazu kommen freie Vermerke. Sind alle Stichproben erledigt, gibst du den Prüfbericht mit deinem Ergebnis ab; danach ist er nicht mehr änderbar und dient als Grundlage der Entlastung. Die Kassenführung sieht abgegebene Berichte (auch als PDF oder CSV). Prüfer buchen nicht, der Kassenwart prüft nicht.": "Kasa denetçileri „Kulüp kasası → Rapor → Kasa denetimi“ altında bir yıl için denetim başlatır – tüm kulüp için veya yalnızca kendi kasaları için. Uygulama istenirse rastgele örnekler çeker; her kayıt işaretlenir veya gerekçeyle itiraz edilir, belgeyi doğrudan görürsün. Buna serbest notlar eklenir. Tüm örnekler tamamlandığında denetim raporunu sonucunla teslim edersin; ardından değiştirilemez ve aklamanın temelini oluşturur. Kasa yönetimi teslim edilen raporları görür (PDF veya CSV olarak da). Denetçiler kayıt yapmaz, veznedar denetlemez.",
