  "Lade Daten als Excel- oder CSV-Datei herunter. Du siehst nur, wofür du Rechte hast; jeder Export wird im Protokoll des Vereins festgehalten.": "Verileri Excel veya CSV dosyası olarak indir. Yalnızca yetkin olanları görürsün; her dışa aktarma kulübün kaydında tutulur.",
  "Lade den Kontoauszug als CSV-Datei deiner Bank hoch. Erkannt werden Buchungstag, Betrag, Name und Verwendungszweck. Zugeordnet wird per Mitgliedsnummer oder Name, wenn der Betrag genau zu einer offenen Forderung passt. Du siehst alles vorher.": "Bankanın CSV dosyası olarak hesap özetini yükle. Kayıt tarihi, tutar, ad ve ödeme amacı tanınır. Tutar tam olarak açık bir alacağa uyuyorsa üye numarasına veya ada göre eşleştirilir. Hepsini önceden görürsün.",
  "Lade den Spielplan als CSV-Datei aus dem DFBnet (Meisterschaft › Vereinsspielplan bzw. Mannschaftsspielplan › Export). Du siehst zuerst eine Vorschau – übernommen wird erst nach deiner Bestätigung. Ein erneuter Import aktualisiert bestehende Spiele, statt sie doppelt anzulegen.": "Fikstürü DFBnet'ten CSV dosyası olarak yükle (Şampiyona › Kulüp fikstürü veya Takım fikstürü › Dışa aktar). Önce bir önizleme görürsün – onayından sonra uygulanır. Tekrar içe aktarma, mevcut maçları mükerrer oluşturmak yerine günceller.",
