  "Lege das Mitglied an und ordne es danach einer Mannschaft zu. Den App-Zugang erhält es später über eine Einladung.": "Üyeyi oluştur ve ardından bir takıma ata. Uygulama erişimini daha sonra bir davetle alır.",
  "Lege Strafen und Beträge fest. Vergebene Strafen landen auf dem Konto der Person; eine spätere Änderung gilt nur für neue Strafen.": "Cezaları ve tutarları belirle. Verilen cezalar kişinin hesabına işlenir; sonraki bir değişiklik yalnızca yeni cezalar için geçerlidir.",
