  "Mich": "Beni",
  "Minderjährig ohne Elternteil und ohne E-Mail – später zuordnen.": "Reşit olmayan, ebeveynsiz ve e-postasız – daha sonra ata.",
  "Mindestens 10 Zeichen – am besten ein kurzer Satz.": "En az 10 karakter – en iyisi kısa bir cümle.",
  "Mindestens 10 Zeichen. Eine Wortfolge oder ein Satz ist sicherer und leichter zu merken als ein kurzes Passwort mit Sonderzeichen.": "En az 10 karakter. Bir kelime dizisi veya cümle, özel karakterli kısa bir şifreden daha güvenli ve akılda tutması daha kolaydır.",
  "Mindestens eine importierte Person hat schon ein Konto. Der Import lässt sich nicht mehr rückgängig machen.": "İçe aktarılan kişilerden en az birinin zaten hesabı var. İçe aktarma artık geri alınamaz.",
  "Mindestens zwei Buchstaben eingeben.": "En az iki harf gir.",
  "Mini-Forum": "Mini forum",
  "Mit Ablaufdatum": "Son kullanma tarihli",
  "Mit App-Zugang": "Uygulama erişimli",
  "Mit dem Start wird {0} zur laufenden Saison. Mannschaftskassen, Mannschaftsdokumente und künftige Termine gehen auf die neuen Mannschaften über. Zuordnungen und Aufgaben der alten Saison enden. Das lässt sich nicht rückgängig machen.": "Başlatıldığında {0} mevcut sezon olur. Takım kasaları, takım belgeleri ve gelecekteki etkinlikler yeni takımlara geçer. Eski sezonun atamaları ve görevleri sona erer. Bu işlem geri alınamaz.",
  "Mit den Pfeilen verschiebst du das Datum um einen Tag. Tippst du auf das Datum selbst, öffnet sich ein Kalender: Wische oder tippe auf die Pfeile, um den Monat zu wechseln, tippe auf einen Tag zum Auswählen oder wähle „Heute“. Nicht erlaubte Tage sind ausgegraut.": "Oklarla tarihi bir gün kaydırırsın. Tarihin kendisine dokunursan bir takvim açılır: ayı değiştirmek için kaydır veya oklara dokun, seçmek için bir güne dokun veya „Bugün“ü seç. İzin verilmeyen günler soluk görünür.",
  "Mit den Schreibweisen aus dem DFBnet ordnet der Spielplan-Import die Spiele richtig zu.": "Fikstür içe aktarma, maçları DFBnet'teki yazımlarla doğru eşleştirir.",
  "Mit der Anschrift füllt Clubroof Spendenbescheinigungen aus; die Zeitzone bestimmt Fristen und Terminzeiten.": "Clubroof, bağış makbuzlarını adresle doldurur; saat dilimi süreleri ve etkinlik saatlerini belirler.",
  "Mit der Zwei-Faktor-Anmeldung braucht jede neue Anmeldung zusätzlich einen Code. Für das Administrationskonto empfehlen wir sie.": "İki faktörlü girişle her yeni giriş ek olarak bir kod gerektirir. Yönetici hesabı için öneriyoruz.",
  "Mit dieser E-Mail-Adresse gibt es bereits ein Konto. Bitte melde dich an oder nutze „Passwort vergessen“.": "Bu e-posta adresiyle zaten bir hesap var. Lütfen giriş yap veya „Şifremi unuttum“u kullan.",
  "Mit Einladungslink oder Einladungscode (auch per QR-Code scannen) trittst du deinem Verein bei – der Verein wird danach auf diesem Gerät gemerkt. Hast du schon ein Konto, melde dich mit E-Mail und Passwort an („Zeigen“ macht das Passwort sichtbar). Einen neuen Verein richtest du mit dem Einrichtungscode (Format CR-XXXX-XXXX) ein, den du von Clubroof nach Zahlungseingang erhältst; er gilt einmal.": "Davet bağlantısı veya davet koduyla (QR kodu tarayarak da) kulübüne katılırsın – kulüp sonra bu cihazda hatırlanır. Zaten hesabın varsa e-posta ve şifreyle giriş yap („Göster“ şifreyi görünür yapar). Yeni bir kulübü, ödeme ulaştıktan sonra Clubroof'tan aldığın kurulum koduyla (biçim CR-XXXX-XXXX) kurarsın; bir kez geçerlidir.",
  "Mit Face ID oder Fingerabdruck entsperren": "Face ID veya parmak iziyle kilidi aç",
  "Mit festen Trainingszeiten stehen die Termine sofort im Kalender, und Zu- und Absagen funktionieren ab dem ersten Tag.": "Sabit antrenman saatleriyle etkinlikler hemen takvimde olur ve katılım ile retler ilk günden çalışır.",
  "Mit Namen": "İsimle",
