  "Mitglieder melden Zahlungen in ihrem Konto. Du siehst sie in der Kassenverwaltung unter „Zahlungsmeldungen“ und bestätigst mit „Eingegangen“ – dann wird die Einzahlung gebucht – oder „Nicht gefunden“.": "Üyeler ödemeleri hesaplarında bildirir. Bunları kasa yönetiminde „Ödeme bildirimleri“ altında görür ve „Ulaştı“ ile onaylarsın – o zaman ödeme kaydedilir – ya da „Bulunamadı“ dersin.",
  "Mitglieder ohne Geburtsdatum werden bei der Jugend-Regel übersprungen und bleiben ohne Beitragsart; Mitglieder mit laufender Beitragsart werden nie verändert.": "Doğum tarihi olmayan üyeler gençlik kuralında atlanır ve aidat türsüz kalır; devam eden aidat türü olan üyeler asla değiştirilmez.",
