  "Name, Kontaktdaten, Mannschaftszugehörigkeit, Zu- und Absagen sowie – nur für Berechtigte – Kassendaten. Gründe für Abwesenheiten sind nur für Trainer und Verantwortliche sichtbar.": "Ad, iletişim bilgileri, takım üyeliği, katılım ve retler ile – yalnızca yetkililer için – kasa verileri. Yokluk nedenleri yalnızca antrenörlere ve sorumlulara görünür.",
