  "Nein. In der Ruhezeit (22 bis 7 Uhr) gibt es keine Push-Nachrichten außer bei dringenden Meldungen. Alles andere wartet bis zum Morgen.": "Hayır. Sessiz saatlerde (22:00 – 07:00) acil bildirimler dışında push mesajı gelmez. Diğer her şey sabaha kadar bekler.",
  "Nein. Trage eine Abwesenheit ein (Urlaub, Verletzt, Krank, Sonstiges). Alle betroffenen Termine werden automatisch abgesagt, das Trainerteam sieht es sofort. Löschst du die Abwesenheit, werden die automatischen Absagen zurückgenommen.": "Hayır. Bir yokluk gir (tatil, sakat, hasta, diğer). Etkilenen tüm etkinlikler otomatik olarak reddedilir, antrenör ekibi bunu hemen görür. Yokluğu silersen otomatik retler geri alınır.",
