  "Nur Admins: Verwaltung › Rollen und Rechte › „Neue Rolle“. Du gibst Name, Beschreibung und den Geltungsbereich (Verein, Abteilung, Mannschaft) an und wählst die Rechte in Klartext; mit „Start als Kopie von“ übernimmst du eine vorhandene Rolle. Sensible Rechte tragen ein Schloss. Vereinsweite Rechte (Verein, Vereinskasse, Mitglieder) gibt es nur in vereinsweiten Rollen, und du kannst nur Rechte vergeben, die du selbst hast. Standardrollen sind geschützt – dort gibt es „Kopie anpassen“. Gelöschte Rollen lassen sich wiederherstellen; Personen stellst du beim Löschen auf eine andere Rolle um. In der Übersicht zeigen die Reiter Rollen, Personen und Matrix den Stand; bei einer Person zeigt „Was darf diese Person?“ jedes Recht mit seiner Quelle.": "Yalnızca yöneticiler: Yönetim › Roller ve yetkiler › „Yeni rol“. Ad, açıklama ve kapsamı (kulüp, bölüm, takım) girer ve yetkileri açık metinle seçersin; „Şunun kopyası olarak başla“ ile mevcut bir rolü devralırsın. Hassas yetkilerde kilit simgesi bulunur. Kulüp genelindeki yetkiler (kulüp, kulüp kasası, üyeler) yalnızca kulüp genelindeki rollerde bulunur ve yalnızca kendinde olan yetkileri verebilirsin. Standart roller korumalıdır – orada „Kopyayı uyarla“ vardır. Silinen roller geri yüklenebilir; silerken kişileri başka bir role geçirirsin. Özette Roller, Kişiler ve Matris sekmeleri durumu gösterir; bir kişide „Bu kişi neler yapabilir?“ her yetkiyi kaynağıyla gösterir.",
