  "Sportliche Leitung": "Sportif yönetim",
  "Sportliche Leitung, Jugendleitung und Vorstand sehen im Reiter „Team“ eine Übersicht über die Abteilungen (Senioren, Frauen, Jugend) – ohne Zugriff in die einzelnen Mannschaften. Oben stehen die Kennzahlen, darunter eine Karte je Mannschaft mit Kader, Trainerteam, Trainingsbeteiligung der letzten 4 Wochen und dem nächsten Spiel. Die Ampel gilt nur für die Trainingsbeteiligung: gut ab 65 %, mittel 50–64 %, niedrig darunter; bei weniger als 3 erfassten Einheiten steht „zu wenig Daten“. Wer auch selbst in einer Mannschaft ist, schaltet oben zwischen „Meine Mannschaft“ und „Übersicht“ um.": "Sportif yönetim, gençlik yönetimi ve yönetim kurulu „Takım“ sekmesinde bölümlerin (yetişkinler, kadınlar, gençlik) özetini görür – tek tek takımlara erişim olmadan. Üstte göstergeler, altında takım başına bir kart yer alır: kadro, antrenör ekibi, son 4 haftanın antrenman katılımı ve sonraki maç. Trafik ışığı yalnızca antrenman katılımı için geçerlidir: %65'ten itibaren iyi, %50–64 orta, altı düşük; 3'ten az kayıtlı antrenmanda „veri yetersiz“ yazar. Kendisi de bir takımda olan kişi üstten „Takımım“ ile „Özet“ arasında geçiş yapar.",
