  "Strafen und ihre Beträge legen Trainerteam und Kassenwart im Strafenkatalog fest („Team → Strafenkatalog“). Wurde dir eine Strafe vergeben, steht sie als offener Betrag auf deinem Konto und du bekommst eine Benachrichtigung.": "Cezaları ve tutarlarını antrenör ekibi ve veznedar ceza kataloğunda belirler („Takım → Ceza kataloğu“). Sana bir ceza verildiyse hesabında açık tutar olarak görünür ve bildirim alırsın.",
