  "Termine, News und Abwesenheiten sind immer dabei. Wähle, was eure Mannschaften zusätzlich brauchen.": "Etkinlikler, haberler ve yokluklar her zaman dahildir. Takımlarınızın ek olarak neye ihtiyacı olduğunu seç.",
