  "Themen": "Konular",
  "Themen eröffnen Verantwortliche im Verein.": "Konuları kulüpteki sorumlular açar.",
  "Themen schließt das Moderationsteam.": "Konuları moderasyon ekibi kapatır.",
  "Tipp: Ort in der Karten-App suchen, „Teilen“ wählen und den Link hier einfügen. Ohne Link nutzt „Route“ die eingetragene Adresse.": "İpucu: Yeri harita uygulamasında ara, „Paylaş“ı seç ve bağlantıyı buraya yapıştır. Bağlantı yoksa „Rota“ kayıtlı adresi kullanır.",
  "Tippe auf der Anmeldeseite auf „Passwort vergessen?“. Du bekommst einen Link per E-Mail, mit dem du ein neues Passwort festlegst. Im Konto kannst du es jederzeit ändern.": "Giriş sayfasında „Şifreni mi unuttun?“a dokun. E-postayla yeni şifre belirleyebileceğin bir bağlantı alırsın. Hesabında istediğin zaman değiştirebilirsin.",
  "Tippe auf die Uhrzeit: Es öffnet sich ein Fenster mit zwei Drehwalzen wie bei einem Wecker – links die Stunde, rechts die Minute (in 5er-Schritten). Wische oder scrolle, bis die richtige Zeit in der Mitte steht, und tippe auf „Übernehmen“. Beim Anlegen eines Termins wählst du Beginn und Ende; die Dauer zeigt die App darunter.": "Saate dokun: bir çalar saat gibi iki çarklı bir pencere açılır – solda saat, sağda dakika (5'er adımlarla). Doğru saat ortada görünene kadar kaydır, sonra „Uygula“ya dokun. Bir etkinlik oluştururken başlangıcı ve bitişi seçersin; süreyi uygulama altında gösterir.",
  "Tippe auf einen Spieler, um seine Rückmeldung zu korrigieren.": "Yanıtını düzeltmek için bir oyuncuya dokun.",
  "Tippe im Termin bei „Teilnehmer“ auf eine Person und wähle Zusage, Unsicher oder Absage. Das geht auch nach Ablauf der Frist (bis eine Woche nach Beginn).": "Etkinlikte „Katılımcılar“ altında bir kişiye dokun ve Katılım, Emin değilim veya Ret'i seç. Bu, süre dolduktan sonra da mümkündür (başlangıçtan bir hafta sonrasına kadar).",
  "Tippe in „Mein Konto“ auf „Bezahlen / Zahlung melden“. Du siehst die Bezahlinfos der Mannschaft (IBAN zum Kopieren, PayPal, bar). Nach dem Bezahlen tippst du „Ich habe bezahlt“. Sobald die Kasse den Eingang bestätigt hat, ist dein Konto ausgeglichen.": "„Hesabım“da „Öde / ödeme bildir“e dokun. Takımın ödeme bilgilerini görürsün (kopyalamak için IBAN, PayPal, nakit). Ödedikten sonra „Ödedim“e dokun. Kasa ödemenin ulaştığını onaylar onaylamaz hesabın dengelenir.",
  "Tippe oben rechts auf die Lupe und gib mindestens zwei Buchstaben ein. Du findest Termine, Mitglieder, News und Mannschaften. Personen siehst du nur, wenn du auch sonst ihr Profil sehen darfst (z. B. aus deiner Mannschaft oder deine Kinder).": "Sağ üstteki büyüteçe dokun ve en az iki harf gir. Etkinlikleri, üyeleri, haberleri ve takımları bulursun. Kişileri yalnızca profillerini başka türlü de görebiliyorsan görürsün (ör. takımından veya çocukların).",
