  "Über das Schild-Symbol oben rechts oder „Ich → Admin-Verwaltung“ oder „Verein → Meine Vereinsaufgaben → Verwaltung“. Mit „Zur App“ kehrst du zur normalen App zurück. Unten wechselst du zwischen Übersicht, Mitgliedern, Teams, Festen und News.": "Sağ üstteki kalkan simgesiyle veya „Ben → Yönetici paneli“ ya da „Kulüp → Kulüp görevlerim → Yönetim“ ile. „Uygulamaya“ ile normal uygulamaya dönersin. Altta Özet, Üyeler, Takımlar, Şenlikler ve Haberler arasında geçiş yaparsın.",
