  "Übliche Strafen als Vorlage – abwählen, was ihr nicht wollt. Beträge und weitere Strafen änderst du später.": "Yaygın cezalar şablon olarak – istemediklerinizin seçimini kaldırın. Tutarları ve diğer cezaları daha sonra değiştirirsin.",
