  "Umlage: Gesamtbetrag auf gewählte Personen aufteilen oder festen Betrag je Person fordern. Beiträge: z. B. 5 € monatlich, die App bucht sie allen Spielern zum Fälligkeitstag. Getränke: Preis festlegen und je Person Striche zählen. Alle Betroffenen werden benachrichtigt.": "Katkı payı: toplam tutarı seçilen kişilere böl veya kişi başı sabit tutar talep et. Aidatlar: ör. aylık 5 €, uygulama bunu vade gününde tüm oyunculara işler. İçecekler: fiyatı belirle ve kişi başı çizgileri say. Tüm ilgililere bildirim gider.",
  "Umsatzsteuer-ID": "KDV kimlik numarası",
