  "Wartet auf Freigabe": "Onay bekliyor",
  "Warum bist du unsicher?": "Neden emin değilsin?",
  "Warum kannst du nicht?": "Neden katılamıyorsun?",
  "Warum wir das fragen": "Bunu neden soruyoruz",
  "Was": "Ne",
  "Was bedeuten die Farben und Abzeichen?": "Renkler ve rozetler ne anlama geliyor?",
  "Was bedeuten die Felder im Kalender?": "Takvimdeki kutular ne anlama geliyor?",
  "Was bedeuten die Hinweise unter den Kacheln?": "Kutucukların altındaki notlar ne anlama geliyor?",
  "Was bedeutet die kleine Zahl oben rechts an den Kacheln?": "Kutucukların sağ üstündeki küçük sayı ne anlama geliyor?",
  "Was bringt „Anwesenheit erfassen“?": "„Yoklama al“ ne işe yarar?",
  "Was darf das Trainerteam in der Kasse?": "Antrenör ekibi kasada neler yapabilir?",
  "Was darf die Mannschaft sehen?": "Takım neleri görebilir?",
  "Was darf diese Person?": "Bu kişi neler yapabilir?",
  "Was ist das Vereinskürzel und wie ändere ich die Vibration?": "Kulüp kısaltması nedir ve titreşimi nasıl değiştiririm?",
  "Was ist die 2-Faktor-Anmeldung?": "İki faktörlü giriş nedir?",
  "Was ist die Absagefrist?": "İptal süresi nedir?",
  "Was ist die Kassenübersicht?": "Kasa özeti nedir?",
  "Was ist die Zeile „Unterstützt von … Anzeige“ und wo sehe ich alle Sponsoren?": "„Destekleyen … Reklam“ satırı nedir ve tüm sponsorları nerede görürüm?",
  "Was ist kaputt?": "Ne bozuldu?",
  "Was ist mit „Ich habe bezahlt“-Meldungen?": "„Ödedim“ bildirimleri ne olur?",
  "Was ist mit Übungsleiter- und Ehrenamtspauschale?": "Antrenör ve gönüllülük ödeneği ne olacak?",
  "Was kann ich als Vereinsmitglied?": "Kulüp üyesi olarak neler yapabilirim?",
  "Was lässt sich außer Mitgliedern importieren?": "Üyeler dışında neler içe aktarılabilir?",
  "Was möchtest du importieren?": "Neyi içe aktarmak istiyorsun?",
  "Was passiert am Ende der Saison mit dem Geld? Das ist ein Hinweis für den Kassenwart; gebucht wird nichts automatisch.": "Sezon sonunda para ne olur? Bu, kasa sorumlusu için bir nottur; otomatik olarak hiçbir şey kaydedilmez.",
  "Was passiert?": "Ne olacak?",
  "Was sehe ich in der Kasse?": "Kasada neleri görürüm?",
  "Was sich in den letzten Versionen verbessert hat (Beispieleinträge).": "Son sürümlerde nelerin iyileştiği (örnek kayıtlar).",
  "Was sind Fundbüro, Forum und Vereinswissen?": "Kayıp eşya bürosu, forum ve kulüp bilgisi nedir?",
  "Was sind Gastspieler?": "Konuk oyuncular nedir?",
  "Was soll der ganze Verein nutzen können? Empfohlenes ist vorausgewählt. „Vereinskasse“ ist nur der Schalter – eingerichtet wird sie danach in einem eigenen Assistenten.": "Tüm kulüp neleri kullanabilmeli? Önerilenler önceden seçili. „Kulüp kasası“ yalnızca şalterdir – kurulumu ardından ayrı bir sihirbazda yapılır.",
  "Was suchst du?": "Ne arıyorsun?",
  "Was zeigt die Abteilungsübersicht im Team-Tab?": "Takım sekmesindeki bölüm özeti ne gösterir?",
  "Was zeigt die Statistik?": "İstatistik ne gösterir?",
  "Was?": "Ne?",
