  "Welche Beitragsarten gibt es? Mit Vorschlägen starten und Beträge anpassen.": "Hangi aidat türleri var? Önerilerle başla ve tutarları uyarla.",
  "Welche Daten habt ihr schon? Die Importe laufen nach der Einrichtung, jeweils mit Vorlage, Spaltenzuordnung und Vorschau. Excel-Dateien mit mehreren Blättern gehen auch – du wählst das Blatt aus.": "Hangi verileriniz zaten var? İçe aktarmalar kurulumdan sonra, her biri şablon, sütun eşleştirme ve önizlemeyle çalışır. Birden fazla sayfalı Excel dosyaları da olur – sayfayı sen seçersin.",
  "Welche Daten wir verarbeiten": "Hangi verileri işliyoruz",
  "Welche Daten wir verarbeiten und warum": "Hangi verileri neden işliyoruz",
  "Welche Kasse?": "Hangi kasa?",
  "Welche Konten und Kassen gibt es?": "Hangi hesaplar ve kasalar var?",
  "Welche Meldungen bekomme ich und wie stelle ich sie ein?": "Hangi bildirimleri alırım ve nasıl ayarlarım?",
  "Welche Vorlage passt?": "Hangi şablon uygun?",
  "Welcher Untergrund?": "Hangi zemin?",
  "Welches Mitglied welche Beitragsart zahlt (ab wann, optional mit abweichendem Betrag). Mitglieder werden über Mitgliedsnummer oder Namen erkannt.": "Hangi üyenin hangi aidat türünü ödediği (ne zamandan itibaren, isteğe bağlı farklı tutarla). Üyeler üye numarası veya adla tanınır.",
  "Wenige Themen, die nach Ablauf schließen – für Absprachen, Ideen und Rückmeldungen. Bitte freundlich bleiben; das Moderationsteam blendet Unpassendes aus.": "Süre dolunca kapanan az sayıda konu – anlaşmalar, fikirler ve geri bildirimler için. Lütfen nazik kal; moderasyon ekibi uygunsuz olanı gizler.",
  "Wenige, moderierte Diskussionsthemen": "Az sayıda, moderasyonlu tartışma konusu",
  "Wenn dein Verein das Sponsoren-Modul nutzt, zeigt ein kleines Wischelement auf Start, im Team-Reiter und im Verein-Reiter bis zu drei Sponsoren, die der Verein als Werbung freigegeben hat. Es ist immer als „Anzeige“ gekennzeichnet und wechselt alle paar Sekunden von selbst; du kannst auch wischen. Ein Tipp öffnet die Seite des Sponsors. Alle Sponsoren findest du unter „Verein → Sponsoren“. Die App wertet nicht aus, wer was ansieht oder antippt. Manche Sponsoren stellt der Verein so ein, dass Jugendspieler sie nicht sehen.": "Kulübün sponsor modülünü kullanıyorsa, ana sayfada, Takım sekmesinde ve Kulüp sekmesinde küçük bir kaydırma öğesi kulübün reklam olarak onayladığı en fazla üç sponsoru gösterir. Her zaman „Reklam“ olarak işaretlidir ve birkaç saniyede bir kendiliğinden değişir; kaydırabilirsin de. Dokunmak sponsorun sayfasını açar. Tüm sponsorları „Kulüp → Sponsorlar“ altında bulursun. Uygulama kimin neye baktığını veya dokunduğunu analiz etmez. Bazı sponsorları kulüp, genç oyuncuların görmeyeceği şekilde ayarlar.",
  "Wenn deine Rückmeldung (oder die deines Kindes) noch fehlt – so lange vor der Frist:": "Senin (veya çocuğunun) yanıtı hâlâ eksikse – süreden bu kadar önce:",
  "Wenn du das nicht warst, ignoriere diese E-Mail – dein Passwort bleibt unverändert.": "Bunu sen yapmadıysan bu e-postayı yok say – şifren değişmeden kalır.",
  "Wenn du dich nicht angemeldet hast, ändere bitte dein Passwort.": "Giriş yapan sen değilsen lütfen şifreni değiştir.",
  "Wenn eine Mannschaft für ein Spiel Spieler braucht, meldet das Trainerteam einen Bedarf. Andere Mannschaften können Spieler abstellen. Du siehst dann den Einsatz im Termin als „Gastspieler“.": "Bir takımın bir maç için oyuncuya ihtiyacı varsa antrenör ekibi bir ihtiyaç bildirir. Diğer takımlar oyuncu bırakabilir. Görevi o zaman etkinlikte „Konuk oyuncu“ olarak görürsün.",
  "Wenn eine Zu- oder Absage noch fehlt": "Bir katılım veya ret hâlâ eksikse",
  "Wenn eingeschaltet, brauchen alle mit Verwaltungsrechten (Vorstand, Admins, Jugendleitung …) die 2-Faktor-Anmeldung, bevor sie Mitgliederdaten bearbeiten können.": "Açıksa yönetim yetkisi olan herkes (yönetim kurulu, yöneticiler, gençlik yönetimi …) üye verilerini düzenlemeden önce iki faktörlü girişe ihtiyaç duyar.",
  "Wer": "Kim",
  "Wer Beiträge und Zuschüsse nach der Saison abrechnet, plant oft lieber in Saisons. Für die Steuererklärung zählt dagegen meist das Kalenderjahr.": "Aidat ve hibeleri sezona göre hesaplayan kulüpler genellikle sezon bazında planlamayı tercih eder. Vergi beyanında ise çoğunlukla takvim yılı geçerlidir.",
  "Wer darf buchen?": "Kim kayıt yapabilir?",
  "Wer darf die Kasse einsehen?": "Kasayı kimler görüntüleyebilir?",
  "Wer deine Daten sieht": "Verilerini kimler görür",
  "Wer die Vereinskasse einsehen darf, bestimmt die Vereinsadministration.": "Kulüp kasasını kimlerin görüntüleyebileceğini kulüp yönetimi belirler.",
  "Wer führt die Kasse?": "Kasayı kim yönetiyor?",
  "Wer gibt Beitrittsanfragen frei?": "Katılım isteklerini kim onaylar?",
  "Wer hat bezahlt?": "Kim ödedi?",
  "Wer hat wann was geändert – die letzten 200 Einträge.": "Kim ne zaman neyi değiştirdi – son 200 kayıt.",
  "Wer hat wie viel getrunken?": "Kim ne kadar içti?",
  "Wer ist dabei? ({0})": "Kimler katılıyor? ({0})",
  "Wer sieht Abwesenheitsgründe?": "Yokluk nedenlerini kimler görür?",
  "Wer sieht die Kontaktdaten neuer Personen? Jede Person kann das für sich ändern.": "Yeni kişilerin iletişim bilgilerini kimler görür? Her kişi bunu kendisi için değiştirebilir.",
  "Wer sieht meine Daten?": "Verilerimi kimler görür?",
  "Wer sieht was von dir": "Senden kim neyi görür",
  "Wer sieht was?": "Kim neyi görür?",
  "Wer sieht, wie viele zu- und abgesagt haben?": "Kaç kişinin katılıp reddettiğini kimler görür?",
  "Wer soll von Anfang an dabei sein? Jede Person bekommt ihre Rolle und eine Einladung per E-Mail, sobald der Verein eingerichtet ist.": "Kimler en başından itibaren dahil olsun? Kulüp kurulur kurulmaz her kişi rolünü ve e-postayla bir davet alır.",
  "Wer spielt in der Mannschaft?": "Takımda kimler oynuyor?",
  "Wer trainiert die Mannschaft?": "Takımı kim çalıştırıyor?",
  "Wer tritt bei?": "Kim katılıyor?",
  "Wer über einen Einladungslink oder QR-Code beitreten will, stellt eine Anfrage. Jemand muss sie freigeben.": "Davet bağlantısı veya QR kodu ile katılmak isteyen herkes bir istek gönderir. Birinin onaylaması gerekir.",
  "Wer über einen Einladungslink oder QR-Code beitreten will, stellt eine Anfrage. Unter „Verwaltung › Verein & Design › Angaben zum Verein“ legst du fest, ob das Trainerteam der Mannschaft entscheidet (Standard; die Verwaltung kann immer freigeben) oder nur die Verwaltung. Die Regel gilt serverseitig: Trainer sehen dann keine Anfragen mehr. Eine Vertretung mit Administrationsrechten bestimmst du im Einrichtungsassistenten oder unter „Rollen & Aufgaben“.": "Davet bağlantısı veya QR kodu ile katılmak isteyen herkes bir istek gönderir. „Yönetim › Kulüp ve tasarım › Kulüp bilgileri“ altında takımın antrenör ekibinin mi karar vereceğini (varsayılan; yönetim her zaman onaylayabilir) yoksa yalnızca yönetimin mi karar vereceğini belirlersin. Kural sunucuda geçerlidir: antrenörler artık hiçbir istek görmez. Yönetim haklarına sahip bir vekili kurulum asistanında veya „Roller ve görevler“ altında belirlersin.",
  "Wer übernimmt?": "Kim üstleniyor?",
  "Wer vertritt dich?": "Seni kim vekil olarak temsil edecek?",
  "Wer zahlt welchen Beitrag?": "Kim hangi aidatı ödüyor?",
  "Wer zugesagt hat oder als Helfer eingetragen ist, erfährt von geänderter Zeit oder geändertem Ort.": "Katılan veya yardımcı olarak kayıtlı olan kişi, değişen saat veya yerden haberdar olur.",
  "Werbung an": "Reklam açık",
  "Werbung in der App": "Uygulamada reklam",
  "Werbung je Sponsor als Wischelement mit Kennzeichnung, Seite „Unsere Sponsoren“": "Sponsor başına reklam, etiketli kaydırma öğesi olarak; „Sponsorlarımız“ sayfası",
  "Werbung läuft für {0} von {1} Sponsoren. Die App zeigt bis zu {2} davon zufällig.": "Reklam {1} sponsordan {0} tanesi için yayında. Uygulama bunlardan en fazla {2} tanesini rastgele gösterir.",
