  "Wie stelle ich Funktionen meiner Mannschaft ein?": "Takımımın işlevlerini nasıl ayarlarım?",
  "Wie suche ich nach Terminen, Personen oder News?": "Etkinlikleri, kişileri veya haberleri nasıl ararım?",
