  "Zuschüsse: Unter „Vereinskasse → Buchung → Zuschüsse“ legst du Förderungen mit Geber, Betrag und Frist für den Verwendungsnachweis an und führst sie von „Geplant“ über „Beantragt“ und „Bewilligt“ bis zum Eingang (Buchung als Einnahme); überfällige Nachweise sind rot. Sponsoren: Beim Buchen einer Einnahme wählst du den Sponsor; unter „Sponsoren“ siehst du die Einnahmen je Sponsor und Jahr. Mannschaftszuschuss: Ausgabe der Vereinskasse und Einnahme der Mannschaftskasse in einem Schritt. Inventar: Unter „Planung → Inventar“ erfasst du Anschaffungen mit Wert und Standort; Gegenstände werden mit Grund ausgesondert, nicht gelöscht.": "Destekler: „Kulüp kasası → Kayıt → Destekler“ altında teşvikleri veren, tutar ve kullanım belgesi süresiyle oluşturur ve „Planlandı“dan „Talep edildi“ ve „Onaylandı“ üzerinden ulaşmaya kadar (gelir olarak kayıt) ilerletirsin; gecikmiş belgeler kırmızıdır. Sponsorlar: Bir gelir kaydederken sponsoru seçersin; „Sponsorlar“ altında sponsor ve yıl başına gelirleri görürsün. Takım desteği: kulüp kasasının gideri ve takım kasasının geliri tek adımda. Envanter: „Planlama → Envanter“ altında alımları değer ve konumla girersin; eşyalar silinmez, nedenle ayıklanır.",
  "Zustand / Hinweis (optional)": "Durum / not (isteğe bağlı)",
  "Zuwendungsbestätigungen haben gesetzliche Pflichtangaben und Formulierungen. Lass die Vorlage von deiner Steuerberatung oder deinem Verband prüfen, bevor du sie freigibst. Die App ersetzt keine Steuerberatung.": "Bağış onay belgelerinin yasal zorunlu bilgileri ve ifadeleri vardır. Onaylamadan önce şablonu vergi danışmanına veya federasyonuna kontrol ettir. Uygulama vergi danışmanlığının yerini almaz.",
